/**
 * The Commission's CBAM tables, and look-ups into them.
 *
 * The data file is generated by scripts/ingest_cbam.py from the official
 * workbooks in data/cbam/sources. It is loaded on demand so the rest of the
 * portal does not carry it.
 */
import Decimal from 'decimal.js';
import type { DefaultUsed, Sector } from './model';

type DvRow = [cn: string, direct: string | null, indirect: string | null, total: string | null, route: string, status: string];
type IvRow = [cn: string, total: string | null, route: string, status: string];
type BmRow = [cn: string, column: 'A' | 'B', value: string | null, indicator: string];

interface Source { doc: string; pdfPage: number; table?: string; file: string; quotes: string[] }

export interface CbamParameters {
  groundRule: string;
  sources: {
    defaultValues: { act: string; annexIV: string; file: string; sha256: string; url: string; fileVersion: string; notIncluded: string };
    benchmarks: { act: string; file: string; sha256: string; url: string; fileVersion: string };
  };
  certificatePrice: {
    quarterly2026: Array<{ quarter: string; published: string; eurPerCertificate: string | null }>;
    rule: string;
    source: { doc: string; url: string; fetched: string };
  };
  markUp: { byYear: Record<string, string>; fromYear2028: string; fertilisers: string; source: Source };
  cbamFactor: { byYear: Record<string, string>; source: Source };
  cscf: { byYear: Record<string, string>; status: string; note: string; source: Source };
  deMinimis: { tonnesPerYear: string; excludedSectors: Sector[]; source: Source };
  indirectCounted: { sectors: Sector[]; source: Source };
  defaultValueRules: { otherCountries: string; annexIV: string; source: Source };
  obligation: { formula: string; source: Source };
  freeAllocation: { processSFA: string; complexSEFA: string; defaultSEFA: string; electricity: string; source: Source };
}

export interface CbamData {
  parameters: CbamParameters;
  goods: Array<[cn: string, description: string, sector: Sector]>;
  countries: string[];
  defaultValues: Record<string, DvRow[]>;
  annexIV: IvRow[];
  benchmarks: BmRow[];
}

export const OTHER_COUNTRIES = 'Other Countries and Territories';

let cached: Promise<CbamData> | null = null;
export function loadCbamData(): Promise<CbamData> {
  if (!cached) cached = import('./data/cbamData.json').then((m) => (m.default ?? m) as unknown as CbamData);
  return cached;
}

export const digits = (cn: string) => cn.replace(/\D/g, '');

/** Format a CN code the way the Commission prints it: 7214 20 00, 2523 10 00 90. */
export function formatCn(cn: string): string {
  const d = digits(cn);
  if (d.length <= 4) return d;
  const parts = [d.slice(0, 4)];
  for (let i = 4; i < d.length; i += 2) parts.push(d.slice(i, i + 2));
  return parts.join(' ');
}

export function goodInfo(data: CbamData, cn: string): { cn: string; description: string; sector: Sector } | null {
  const d = digits(cn);
  // The most specific listed code that the entered code starts with (or that starts with it).
  let best: CbamData['goods'][number] | null = null;
  for (const g of data.goods) {
    if (d.startsWith(g[0]) && (!best || g[0].length > best[0].length)) best = g;
  }
  if (!best) {
    const longer = data.goods.filter((g) => g[0].startsWith(d));
    if (longer.length && new Set(longer.map((g) => g[2])).size === 1) best = longer[0];
  }
  return best ? { cn: best[0], description: best[1], sector: best[2] } : null;
}

export function sectorOf(data: CbamData, cn: string): Sector | null {
  return goodInfo(data, cn)?.sector ?? null;
}

export function indirectCounts(data: CbamData, sector: Sector | null): boolean {
  return !!sector && data.parameters.indirectCounted.sectors.includes(sector);
}

export function markUpFor(data: CbamData, sector: Sector | null, year: number): string {
  if (sector === 'fertilisers') return data.parameters.markUp.fertilisers;
  // Imports in 2026 always use 2026 (Guidance No. 4, reporting period rules); no earlier year exists.
  const y = Math.max(year, 2026);
  return data.parameters.markUp.byYear[String(y)] ?? data.parameters.markUp.fromYear2028;
}

export function cbamFactorFor(data: CbamData, year: number): string | null {
  return data.parameters.cbamFactor.byYear[String(Math.max(year, 2026))] ?? null;
}

export function cscfFor(data: CbamData, year: number, override?: string): { value: string; preliminary: boolean } | null {
  if (override && override.trim()) return { value: override.trim(), preliminary: false };
  const v = data.parameters.cscf.byYear[String(Math.max(year, 2026))];
  return v ? { value: v, preliminary: data.parameters.cscf.status === 'preliminary' } : null;
}

/** The most specific row whose CN code prefixes the entered code. "see below" rows are headings, not values. */
function bestRow<T extends { 0: string }>(rows: T[], cn: string, isHeading: (r: T) => boolean): T | null {
  const d = digits(cn);
  let best: T | null = null;
  for (const r of rows) {
    if (isHeading(r)) continue;
    if (d.startsWith(r[0]) && (!best || r[0].length > best[0].length)) best = r;
  }
  return best;
}

export type DefaultLookup =
  | { ok: true; used: DefaultUsed; direct: string; indirect: string; counted: string; routes: string[] }
  | { ok: false; reason: string };

/**
 * Default specific embedded emissions for a good, including the mark-up.
 *
 * country: the country of production, or null when unknown. For a final good
 * an unknown country uses 'Other countries and territories'; for a precursor
 * it uses Annex IV (asPrecursor).
 */
export function lookupDefault(
  data: CbamData, cn: string, country: string | null, year: number, asPrecursor = false,
): DefaultLookup {
  const sector = sectorOf(data, cn);
  if (sector === 'electricity') {
    return { ok: false, reason: 'Default values for electricity (Annex III to Regulation 2025/2621) are not loaded: enter actual data.' };
  }
  const markUp = markUpFor(data, sector, year);
  const factor = new Decimal(1).plus(markUp);
  const counts = indirectCounts(data, sector);
  const heading = (r: DvRow) => r[5] === 'see_below';

  const fromAnnexI = (table: string, rows: DvRow[] | undefined, note?: string): DefaultLookup | null => {
    if (!rows) return null;
    const row = bestRow(rows, cn, heading);
    if (!row || row[5] !== 'value' || row[3] == null) return null;
    const direct = row[1] ?? row[3];
    const indirect = counts && row[2] != null ? row[2] : '0';
    const total = row[3];
    const directM = new Decimal(direct).times(factor);
    const indirectM = new Decimal(indirect).times(factor);
    return {
      ok: true,
      direct: directM.toString(),
      indirect: indirectM.toString(),
      counted: new Decimal(total).times(factor).toString(),
      routes: splitRoutes(row[4]),
      used: {
        cn, matchedCn: row[0], table, direct: row[1], indirect: row[2], total, markUp, year,
        totalWithMarkUp: new Decimal(total).times(factor).toString(), route: row[4], note,
      },
    };
  };

  if (asPrecursor && country === null) {
    const row = bestRow(data.annexIV, cn, (r) => r[3] === 'see_below');
    if (!row || row[3] !== 'value' || row[1] == null) {
      return { ok: false, reason: `No Annex IV value is published for CN ${formatCn(cn)}.` };
    }
    const total = new Decimal(row[1]).times(factor);
    return {
      ok: true, direct: total.toString(), indirect: '0', counted: total.toString(), routes: splitRoutes(row[2]),
      used: {
        cn, matchedCn: row[0], table: 'Annex IV (highest default value; country of production unknown)',
        direct: null, indirect: null, total: row[1], markUp, year, totalWithMarkUp: total.toString(), route: row[2],
        note: 'Annex IV gives the total only; it is counted as direct emissions here.',
      },
    };
  }

  if (country && country !== OTHER_COUNTRIES) {
    const hit = fromAnnexI(`Annex I – ${country}`, data.defaultValues[country]);
    if (hit) return hit;
  }
  const fallbackNote = country && country !== OTHER_COUNTRIES
    ? `No value for ${country}; 'Other countries and territories' applies.` : undefined;
  const other = fromAnnexI(`Annex I – ${OTHER_COUNTRIES}`, data.defaultValues[OTHER_COUNTRIES], fallbackNote);
  if (other) return other;
  return { ok: false, reason: `No default value is published for CN ${formatCn(cn)}.` };
}

function splitRoutes(route: string): string[] {
  return route ? route.split('/').map((r) => r.trim()).filter(Boolean) : [];
}

export type BenchmarkLookup =
  | { ok: true; value: string; indicator: string; matchedCn: string }
  | { ok: false; reason: string; options?: string[] };

const YEAR_INDICATOR = (year: number) => (year <= 2027 ? '(1)' : '(2)');

/**
 * CBAM benchmark (Column A: process; Column B: whole chain, used with default values).
 * Benchmarks are listed at 8-digit CN level; longer TARIC codes use their first 8 digits.
 */
export function lookupBenchmark(
  data: CbamData, cn: string, column: 'A' | 'B', route: string | undefined, year: number,
): BenchmarkLookup {
  const d = digits(cn).slice(0, 8);
  let rows = data.benchmarks.filter((r) => r[1] === column && r[0] === d);
  if (!rows.length) {
    const longer = data.benchmarks.filter((r) => r[1] === column && r[0].startsWith(d));
    const values = new Set(longer.map((r) => `${r[2]}|${r[3]}`));
    const codes = new Set(longer.map((r) => r[0]));
    if (codes.size > 1 && values.size > 1) {
      return { ok: false, reason: `Benchmarks differ within CN ${formatCn(d)}: choose the 8-digit CN code.`, options: [...codes] };
    }
    rows = longer.filter((r) => r[0] === [...codes][0]);
  }
  if (!rows.length) return { ok: false, reason: `No CBAM benchmark is listed for CN ${formatCn(d)}.` };
  if (rows.length === 1) return { ok: true, value: rows[0][2] ?? '0', indicator: rows[0][3], matchedCn: rows[0][0] };
  const byYear = rows.find((r) => r[3] === YEAR_INDICATOR(year));
  if (byYear) return { ok: true, value: byYear[2] ?? '0', indicator: byYear[3], matchedCn: byYear[0] };
  if (route) {
    const hit = rows.find((r) => r[3] === route);
    if (hit) return { ok: true, value: hit[2] ?? '0', indicator: hit[3], matchedCn: hit[0] };
  }
  return {
    ok: false,
    reason: `The benchmark for CN ${formatCn(d)} depends on the production route: choose one.`,
    options: rows.map((r) => r[3]),
  };
}

